using System;namespace Recovered.Gameplay {public static class PtlTokenCrc {public static uint Initialize(SoundSetupImage m,uint receiver){for(uint i=0;i<256;i++){uint value=i<<8;for(int b=0;b<8;b++)value=((value<<1)^((value&0x8000)!=0?0x1021u:0))&65535;m.Word(0x297d698+i*4,value);}return receiver;}static uint Step(SoundSetupImage m,uint crc,byte value){uint index=((crc>>8)^value)&255;return ((crc<<8)^m.Word(0x297d698+index*4))&65535;}public static uint Forward(SoundSetupImage m,uint bytes,int length){uint value=65535;for(int i=0;i<length;i++)value=Step(m,value,m.Byte(unchecked(bytes+(uint)i)));return value;}public static uint Reverse(SoundSetupImage m,uint bytes,int length){uint value=65535,p=unchecked(bytes+(uint)length);for(int i=0;i<length;i++){p=unchecked(p-1);value=Step(m,value,m.Byte(p));}return value;}public static uint Values(SoundSetupImage m,byte[] bytes,bool reverse){uint crc=65535;for(int i=0;i<bytes.Length;i++)crc=Step(m,crc,bytes[reverse?bytes.Length-1-i:i]);return crc;}}}
